var wanted = ['⚔ Bolt rifle → Termagants', '▸ Weapon 1 of 2', '1· HIT 3+', '2· WOUND 4+', '3· SAVE 5+', '4· DAMAGE D6', '5· FNP 5+', '7/9 hit', '(3 crit)', '+1 to hit', '5/7 wound', 'Wound modifier: +1', '2 saved', '3 failed', '4+ base save, AP-1', '= 6 damage', '2/4 prevented', 'CHARGE 2D6', '= 9"', 'Charge successful']
for w in wanted:
	if not t.contains(w):
		return 'MISSING: %s' % w
return 'ALL_PRESENT'
